#include "ec.hpp"
#include <filesystem>
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];need(!std::filesystem::exists(root+"/data/fixtures.json"),"refuse fixture overwrite");json nodes=json::array(),edges=json::array();std::ifstream in(root+"/data/discovery.jsonl");std::string line;while(std::getline(in,line)){auto j=json::parse(line);if(j["type"]=="node")nodes.push_back(j);else edges.push_back(j);}need(nodes.size()==46&&edges.size()==90,"component size");need(prime(PRIME)&&prime(ORDER)&&TOTAL==4*ORDER,"prime/order identity");std::vector<std::vector<int>>adj(46);for(auto&e:edges){int a=e["source"],b=e["target"];adj[a].push_back(b);}
 int center=-1,radius=100;std::vector<int>levels;for(int s=0;s<46;s++){std::vector<int>d(46,-1);d[s]=0;std::queue<int>q;q.push(s);while(!q.empty()){int x=q.front();q.pop();for(int y:adj[x])if(d[y]<0){d[y]=d[x]+1;q.push(y);}}need(std::none_of(d.begin(),d.end(),[](int x){return x<0;}),"disconnected");int r=*std::max_element(d.begin(),d.end());if(r<radius){radius=r;center=s;levels=d;}}
 need(radius==4&&center>=0,"depth mismatch");std::array<int,5>counts{};for(int i=0;i<46;i++){counts[levels[i]]++;nodes[i]["level"]=levels[i];need(adj[i].size()==(levels[i]==4?1U:3U),"valency mismatch");need(val(nodes[i]["order"])==TOTAL,"point count mismatch");U product=1;for(auto&f:nodes[i]["group_invariant_factors"])product*=val(f);need(product==TOTAL,"invariant product");}need(counts==std::array<int,5>{1,3,6,12,24},"level population");
 Random rng(root+"/data/randomness.jsonl");std::vector<U>ks,seeds;std::set<U>distinct;while(ks.size()<10){U k=rng.below(ORDER-1,"scalar")+1;if(distinct.insert(k).second)ks.push_back(k);}for(int i=0;i<100;i++)seeds.push_back(rng.below(UINT64_MAX-1,"rho_seed/"+std::to_string(i))+1);
 EC source{val(nodes[0]["a"]),val(nodes[0]["b"])};std::vector<Point>gens;std::set<std::pair<U,U>>keys;while(gens.size()<10){Point P=sample(source,rng,"generator/"+std::to_string(gens.size()));auto key=std::make_pair(P.x,std::min(P.y,PRIME-P.y));if(keys.insert(key).second)gens.push_back(P);}
 json all=json::object(),witness=json::array(),sourceRows=json::array();for(int g=0;g<10;g++)for(int k=0;k<10;k++){int id=g*10+k;Point Q=source.scalar(ks[k],gens[g]);sourceRows.push_back({{"id",id},{"generator",g},{"key_index",k},{"P",wire(gens[g])},{"Q",wire(Q)},{"rho_seed",std::to_string(seeds[id])},{"point_order",std::to_string(ORDER)},{"target_order",std::to_string(ORDER)}});witness.push_back({{"id",id},{"k",std::to_string(ks[k])}});}all["0"]=sourceRows;
 U checks=0;for(int i=0;i<46;i++){EC ec{val(nodes[i]["a"]),val(nodes[i]["b"])};if(i){int parent=nodes[i]["parent"],eid=nodes[i]["discovery_edge"];need(parent>=0&&parent<i,"parent index");auto&e=edges[eid];need(e["source"]==parent&&e["target"]==i,"discovery map");auto rows=all[std::to_string(parent)];for(auto&row:rows){row["P"]=wire(map_point(point(row["P"]),e));row["Q"]=wire(map_point(point(row["Q"]),e));}all[std::to_string(i)]=rows;}
 for(auto&row:all[std::to_string(i)]){Point P=point(row["P"]),Q=point(row["Q"]);need(!P.infinity&&!Q.infinity&&ec.on(P)&&ec.on(Q),"fixture on-curve");need(ec.scalar(ORDER,P).infinity&&ec.scalar(ORDER,Q).infinity,"fixture exact prime orders");need(ec.scalar(ks[row["key_index"].get<int>()],P)==Q,"transported relation");checks++;}}
 U edgeChecks=0,homChecks=0;for(auto&e:edges){int a=e["source"],b=e["target"];EC ea{val(nodes[a]["a"]),val(nodes[a]["b"])},eb{val(nodes[b]["a"]),val(nodes[b]["b"])};Point kernel{val(e["kernel_x"]),0,false};need(ea.on(kernel)&&ea.scalar(2,kernel).infinity,"kernel order2");int reverse=-1;for(auto&rev:edges)if(rev["source"]==b&&rev["target"]==a){need(reverse<0,"multiple reverse maps");reverse=rev["id"];}need(reverse>=0,"missing reverse");e["dual_id"]=reverse;
 for(auto&row:all[std::to_string(a)]){Point P=map_point(point(row["P"]),e),Q=map_point(point(row["Q"]),e);need(!P.infinity&&!Q.infinity&&eb.on(P)&&eb.on(Q),"edge image membership");need(eb.scalar(ORDER,P).infinity&&eb.scalar(ORDER,Q).infinity,"edge image exact orders");need(eb.scalar(ks[row["key_index"].get<int>()],P)==Q,"edge discrete-log transport");edgeChecks++;}
 for(int g=0;g<10;g++){Point P=point(all[std::to_string(a)][g*10]["P"]),Q=point(all[std::to_string(a)][((g+1)%10)*10]["P"]);need(map_point(ea.op(P,Q),e)==eb.op(map_point(P,e),map_point(Q,e)),"homomorphism");homChecks++;Point c=map_point(map_point(P,e),edges[reverse]),two=ea.scalar(2,P);need(c==two||c==ea.neg(two),"dual composition +/-2");}}
 json seedwire=json::array();for(U s:seeds)seedwire.push_back(std::to_string(s));save(root+"/data/family.json",{{"p",std::to_string(PRIME)},{"order",std::to_string(TOTAL)},{"subgroup_order",std::to_string(ORDER)},{"ell",2},{"coverage","complete_selected_component"},{"center",center},{"level_populations",counts},{"fixed_odd_conductor","14549535"},{"nodes",nodes},{"edges",edges}});save(root+"/data/fixtures.json",all);save(root+"/data/checker_answers.json",witness);save(root+"/data/rho_seeds.json",seedwire);save(root+"/data/native_validation.json",{{"passed",true},{"fresh_run",true},{"field_and_subgroup_prime",true},{"fixtures_verified",checks},{"directed_edge_fixture_checks",edgeChecks},{"homomorphism_and_dual_checks",homChecks},{"levels",counts},{"center",center},{"raw_random_words",rng.index},{"solver_inputs_contain_expected_scalar",false}});std::cout<<"Fresh graph 46 curves / 90 maps; "<<checks<<" fixtures; "<<edgeChecks<<" edge cases; "<<homChecks<<" homomorphism controls verified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
